SELECT *
FROM t_position


        AND deleted_flag = #{queryForm.deletedFlag}


        AND position_name LIKE CONCAT('%', #{queryForm.positionName}, '%')


        AND category = #{queryForm.category}


        AND status = #{queryForm.status}


        AND position_level = #{queryForm.positionLevel}


ORDER BY sort ASC, position_id ASC
